ToggleGroup.description:
A row of Toggles tracking which are pressed: one at a time, or several with `multiple: true`.

  ToggleGroup(default_value: [ "center" ], aria_label: "Text alignment") do
    Toggle(value: "left", aria_label: "Align left") { |t| Button(**t, variant: :ghost, icon: true) { Icon(:align_left) } }
    Toggle(value: "center", aria_label: "Align center") { |t| Button(**t, variant: :ghost, icon: true) { Icon(:align_center) } }
  end

The row is one tab stop; the arrow keys move along `orientation:` (wrapping with `loop_focus:`). `name:` submits the pressed value as `name` (or, `multiple: true`, the pressed values as `name[]` fields); `include_hidden: true` adds an empty one first, so pressing nothing still submits the key. Emits `appica-ui--toggle-group:change` with { value } (the pressed values). It's a `role="group"` - name it with aria_label(ledby), or put it in a Field.

examples.code:
phlex do
  Toggle(pressed:, disabled:, **given(value:, name:), aria_label: "Bold") { |toggle| Button(**toggle, variant:, icon: true) { Icon(:bold) } }
end

phlex do
  div(class: "flex items-center gap-2") do
    Toggle(pressed: true, aria_label: "Bold") { |toggle| Button(**toggle, variant: :outline, icon: true) { Icon(:bold) } }
    Toggle(aria_label: "Italic") { |toggle| Button(**toggle, variant: :outline, icon: true) { Icon(:italic) } }
    Toggle(aria_label: "Underline") { |toggle| Button(**toggle, variant: :outline, icon: true) { Icon(:underline) } }
  end
end

phlex do
  div(class: "flex flex-wrap items-center gap-3") do
    Toggle { |toggle| Button(**toggle, variant: :outline) { "Off" } }
    Toggle(pressed: true) { |toggle| Button(**toggle, variant: :outline) { "Pressed" } }
    Toggle(disabled: true) { |toggle| Button(**toggle, variant: :outline) { "Disabled" } }
  end
end

phlex do
  div(dir: "rtl", class: "flex items-center gap-2") do
    Toggle(pressed: true) { |toggle| Button(**toggle, variant: :outline) { "عريض" } }
    Toggle { |toggle| Button(**toggle, variant: :outline) { "مائل" } }
  end
end

phlex do
  ToggleGroup(default_value: [ "center" ], aria_label: "Text alignment") { instance_exec(&ALIGNMENT_TOGGLES) }
end

phlex do
  ToggleGroup(orientation: :vertical, default_value: [ "left" ], aria_label: "Text alignment") { instance_exec(&ALIGNMENT_TOGGLES) }
end

phlex do
  ToggleGroup(disabled: true, default_value: [ "center" ], aria_label: "Text alignment") { instance_exec(&ALIGNMENT_TOGGLES) }
end

phlex do
  ToggleGroup(dir: "rtl", default_value: [ "right" ], aria_label: "محاذاة النص") { instance_exec(&ALIGNMENT_TOGGLES) }
end
